import {createCanvas} from './vendor/ecs-canvas/canvas.js';
const $=id=>document.getElementById(id),esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c])),pretty=x=>JSON.stringify(x,null,2);
const params=new URLSearchParams(location.search),story=params.get('story')||'default';let resizeGuard;let recipe=null,model=null,resultId=params.get('result'),canvas=null,job=null,expanded=new Set(),selection=null,steps=[];
const status=(message,error=false)=>{$('utStatus').textContent=message;$('utStatus').className=error?'error':'';};
async function request(url,body){const r=await fetch(url,{method:body?'POST':'GET',headers:{'content-type':'application/json','x-dt-story':story},...(body?{body:JSON.stringify(body)}:{})});const value=await r.json();if(!r.ok)throw Error(value.error?.message||value.error||(r.status===403?'Sign in through Admin, then reopen this task.':'Request failed'));return value;}
const tool=async(name,args)=>(await request('/api/tool/'+name,args)).result;
async function busy(fn){for(const id of ['utSave','utBuild','utReplay','utNew','utRecipe'])$(id).disabled=true;try{await fn();}catch(e){status(e.message,true);}finally{$('utSave').disabled=false;$('utNew').disabled=false;$('utRecipe').disabled=false;$('utBuild').disabled=!recipe;$('utReplay').disabled=!recipe;}}
async function list(){const r=await tool('ui_trace_list',{}),env=$('utEnv').value||params.get('env')||model?.env;const envs=r.envs||[model?.env||'dev'];$('utEnv').innerHTML=envs.map(e=>`<option value="${esc(e)}">${esc(e)}</option>`).join('');$('utEnv').value=envs.includes(env)?env:envs[0];$('utRecipe').innerHTML='<option value="">Choose a saved UI state…</option>'+r.recipes.map(r=>`<option value="${esc(r.id)}">${esc(r.title)} · ${esc(r.id)}</option>`).join('');if(recipe)$('utRecipe').value=recipe.id;}
const bindingKeys=['services','fields','transports','databases','database_links'];
function edit(r){recipe=r;const d=r.definition;$('utId').value=r.id;$('utName').value=d.title;$('utUrl').value=d.recipe.url;$('utBindings').value=pretty(Object.fromEntries(bindingKeys.map(k=>[k,d[k]||[]])));steps=structuredClone(d.recipe.steps);renderSteps();runtimeParams();$('utBuild').disabled=false;$('utReplay').disabled=false;$('utRecipe').value=r.id;}
function renderSteps(){
 $('utSteps').innerHTML=steps.map((s,i)=>`<div class="ut-step"><label>Action<select data-step="${i}" data-prop="action">${['navigate','fill','click','select','check','press','wait'].map(a=>`<option ${s.action===a?'selected':''}>${a}</option>`).join('')}</select></label><label>${s.action==='navigate'?'URL':'CSS selector (or use role)'}<input data-step="${i}" data-prop="${s.action==='navigate'?'url':'selector'}" value="${esc(s.url||s.selector||'')}" placeholder="${s.action==='navigate'?'https://…':'[name=orderId]'}"></label><label>Role / exact name<input data-step="${i}" data-prop="accessible" value="${esc(s.role?s.role+' / '+s.name:'')}" placeholder="button / Search" ${s.action==='navigate'?'disabled':''}></label><label>Value<input data-step="${i}" data-prop="value" value="${esc(s.value||'')}" placeholder="{{orderId}}" ${['fill','select','press'].includes(s.action)?'':'disabled'}></label><button data-remove="${i}" aria-label="Remove action ${i+1}">Remove</button></div>`).join('');
 for(const e of $('utSteps').querySelectorAll('[data-step]'))e.onchange=()=>{const i=Number(e.dataset.step),p=e.dataset.prop;if(p==='accessible'){const parts=e.value.split(' / ');delete steps[i].selector;steps[i].role=parts.shift();steps[i].name=parts.join(' / ');}else if(p==='selector'){steps[i].selector=e.value;delete steps[i].role;delete steps[i].name;}else if(p==='action'){steps[i]={action:e.value};renderSteps();}else steps[i][p]=e.value;runtimeParams();};
 for(const b of $('utSteps').querySelectorAll('[data-remove]'))b.onclick=()=>{steps.splice(Number(b.dataset.remove),1);renderSteps();runtimeParams();};
}
function definition(){const b=JSON.parse($('utBindings').value);return {title:$('utName').value,description:recipe?.definition?.description||'',recipe:{url:$('utUrl').value,steps},...Object.fromEntries(bindingKeys.map(k=>[k,b[k]||[]]))};}
function runtimeParams(){const values=Object.fromEntries([...$('utParamFields').querySelectorAll('input')].map(e=>[e.dataset.param,e.value])),names=[...new Set([...JSON.stringify({url:$('utUrl').value,steps}).matchAll(/\{\{(\w+)\}\}/g)].map(m=>m[1]))];$('utParams').hidden=!names.length;$('utParamFields').innerHTML=names.map(n=>`<label>${esc(n)}<input data-param="${esc(n)}" type="password" autocomplete="off" value="${esc(values[n]||'')}"></label>`).join('');}
async function save(){const value=await tool('ui_trace_save',{id:$('utId').value,expected_revision:recipe?.id===$('utId').value?recipe.revision:null,definition:definition()});edit(value);await list();status('Recipe saved. Replay and database queries run only when you choose their action.');return value;}
async function build(capture){
 const runtime=Object.fromEntries([...$('utParamFields').querySelectorAll('input')].map(e=>[e.dataset.param,e.value]));await save();status(capture?'Replaying saved UI actions and capturing requests…':'Joining retained browser evidence to exact source snapshots…');
 let r;try{r=await tool('ui_trace',{id:recipe.id,revision:recipe.revision,env:$('utEnv').value||model?.env,capture,...(capture?{params:runtime}:{}),...(!capture&&resultId?{previous:resultId}:{})});}finally{for(const e of $('utParamFields').querySelectorAll('input'))e.value='';}
 job=r.job;$('utCancel').hidden=!job||r.state!=='running';
 while(r.state==='running'){status('UI trace job running · '+job+' · you can cancel below');await new Promise(resolve=>setTimeout(resolve,900));r=await tool('ui_trace',{job,waitMs:1000});}
 $('utCancel').hidden=true;job=null;if(!r.view)throw Error(r.error||'No diagram was produced. Inspect this job in Admin Runtime.');await loadResult(r.view.split('/').pop());status('Diagram saved. Browser observations, static paths and declared field mappings remain separate.');
}
async function loadResult(id){const r=await request('/api/result/'+encodeURIComponent(id));if(r.view!=='ui-trace')throw Error('This result is not a UI trace');model=r.data;resultId=id;expanded.clear();edit({id:model.id,revision:model.revision,definition:model.definition});$('utTitle').textContent=model.title;$('utEnv').value=model.env;$('utSummary').textContent=`${model.counts.requests} requests · ${model.counts.services} services · ${model.counts.states} static states · ${model.counts.routines||0} routines · ${model.counts.fields} fields · ${model.env}`;$('utGapSummary').textContent=`Coverage & assumptions (${model.gaps.length})`;$('utGaps').innerHTML=model.gaps.map(g=>`<article><strong>${esc(g.kind)}</strong><p>${esc(g.detail)}</p><small>${esc([g.service,g.object,g.file&&g.file+':'+g.line].filter(Boolean).join(' · '))}</small></article>`).join('');$('utJson').disabled=false;$('utSvg').disabled=false;$('utEmpty').hidden=!!model.nodes.length;params.set('result',id);params.set('story',story);history.replaceState(null,'','?'+params);const selected=model.nodes.find(n=>n.id===params.get('node'));if(selected?.service)expanded.add('service:'+selected.service);draw();outline();inspect(selected?.id||'ui');if(selected)canvas.ctx.bus.emit('view.fit.item',{kind:'node',id:selected.id});status('Retained diagram loaded. Replay and SQL run only when you choose their action.');}
const themeMedia=matchMedia('(prefers-color-scheme: dark)');
function syncTheme(){if(!canvas)return;const desired=themeMedia.matches?'dark':'light',shell=$('utCanvas').querySelector('.shell');if(shell){shell.dataset.theme=desired;shell.dataset.colorscheme=desired;}}
themeMedia.addEventListener('change',syncTheme);
function preserveCamera(){if(canvas)for(const key of ['view.resize.fit','view.fit.settle','camera.animate'])canvas.ctx.frameLoop.cancel(key);}
function draw(){
 if(!model)return;
 const previous=canvas?{...canvas.ctx.contexts.view.get()}:null;preserveCamera();
 if(!canvas){canvas=createCanvas({target:$('utCanvas'),mode:'read-only',ui:{fit:'contain',panels:false,inheritHotkeys:false}});canvas.ctx.runtime.setFlag('containers',true);addEventListener('resize',preserveCamera);if(typeof ResizeObserver==='function'){resizeGuard=new ResizeObserver(preserveCamera);resizeGuard.observe($('utCanvas').querySelector('[data-place=stage]'));}canvas.ctx.bus.on('selection.changed',()=>{const s=canvas.ctx.selection.selected();if(s?.kind==='node')inspect(s.id);else if(s?.kind==='edge')inspectEdge(s.id);});}
 canvas.load(dtUiTraceLayout.project(model,[...expanded]).canvas);preserveCamera();
 // Overview is explicit. Start at the screenshot, then preserve the user's camera.
 const camera=previous||{x:0,y:0,scale:.9};canvas.ctx.contexts.view.set(camera);canvas.ctx.bus.emit('view.changed',camera);queueMicrotask(syncTheme);
 window.__uiTrace={model,expanded:[...expanded],ready:true,camera:()=>({...canvas.ctx.contexts.view.get()}),focus:id=>canvas.ctx.bus.emit('view.fit.item',{kind:'node',id})};
}
function outline(){if(!model)return;const q=$('utSearch').value.toLowerCase(),matches=n=>(n.name+' '+(n.file||'')+' '+(n.service||'')).toLowerCase().includes(q);const button=n=>`<button data-node="${esc(n.id)}" aria-current="${n.id===selection}">${esc(n.name?.slice(0,120)||n.kind)}<small>${esc(n.kind)}${n.line?' · '+n.line:''}</small></button>`;const primary=model.nodes.filter(n=>!n.service&&matches(n));$('utNodes').innerHTML=primary.map(button).join('')+model.nodes.filter(n=>n.kind==='service').map(s=>`<details ${q?'open':''}><summary>${esc(s.name)}</summary>${model.nodes.filter(n=>n.service===s.name&&matches(n)).map(button).join('')}</details>`).join('');for(const b of $('utNodes').querySelectorAll('button'))b.onclick=()=>{const n=model.nodes.find(n=>n.id===b.dataset.node);if(n.service&&!expanded.has('service:'+n.service)){expanded.add('service:'+n.service);draw();}inspect(b.dataset.node);canvas?.ctx.bus.emit('view.fit.item',{kind:'node',id:b.dataset.node});};}
function inspectEdge(id){const e=model.edges.find(e=>e.id===id);if(!e)return;$('utInspect').innerHTML=`<h2>${esc(e.label)}</h2><span class="ut-badge">${esc(e.certainty)}</span><p>${esc(e.from)} → ${esc(e.to)}</p><pre>${esc(pretty(e.evidence))}</pre><p>${esc(e.assumption||'Static and declared bindings do not prove observed execution or value equality.')}</p>`;}
const isFunction=n=>n.kind==='function'||['function','procedure','aggregate','window'].includes(n.objectKind);
function draft(n){if(isFunction(n))return null;const quote=x=>'"'+x.replace(/"/g,'""')+'"',parts=n.object?.split('.');if(parts?.length!==2)return null;const fields=n.column?quote(n.column):(n.columns||[]).slice(0,8).map(c=>quote(c.name)).join(', ');return fields?{env:model.env,db:n.db,sql:`SELECT ${fields} FROM ${parts.map(quote).join('.')} WHERE FALSE LIMIT 20`}:null;}
function inspect(id){selection=id;const n=model.nodes.find(n=>n.id===id);if(!n)return;for(const b of $('utNodes').querySelectorAll('[data-node]'))b.setAttribute('aria-current',String(b.dataset.node===id));const edges=model.edges.filter(e=>e.from===id||e.to===id);const isService=n.kind==='service',d=['table','column'].includes(n.kind)?draft(n):null;
 $('utInspect').innerHTML=`<h2>${esc(n.name||n.kind)}</h2><span class="ut-badge">${esc(n.kind)}</span>${n.type?`<span class="ut-badge">${esc(n.type)}</span>`:''}${n.kind==='ui'?`${n.state?.image?`<img alt="Last captured UI state" src="data:${esc(n.state.image.mimeType)};base64,${esc(n.state.image.data)}">`:'<p>No screenshot retained. Replay the recipe to capture it.</p>'}<p class="ut-source">${esc(n.state?.url||'')}<br>${esc(n.state?.capturedAt||'Not yet captured')}</p><button id="utEditSelected">Edit replay steps</button><pre>${esc(pretty(model.definition.recipe))}</pre>`:''}${isService?`<button id="utExpand">${expanded.has(id)?'Collapse service':'Expand static path'}</button><p>${model.groups.filter(g=>g.service===n.name).map(g=>esc(g.repo+' @ '+g.sha.slice(0,12)+' · analysis '+g.analysis.slice(0,12))).join('<br>')||'No exact retained source path was resolved. Inspect coverage gaps or supply an exact entry binding.'}</p>`:''}${n.exchange?`<p>Observed HTTP status: ${esc(n.status||'pending')}</p><p class="ut-source">${esc(n.url)}</p><a href="/api-client?exchange=${encodeURIComponent(n.exchange)}&story=${encodeURIComponent(story)}" target="_blank" rel="noopener">Inspect API request & response</a>`:''}${n.file?`<p class="ut-source">${esc(n.repo)} @ ${esc(n.sha?.slice(0,12))}<br>${esc(n.file)}:${esc(n.line)}</p><pre>${esc(n.code)}</pre><p>${esc(pretty({changes:n.changes||[],assumptions:n.assumptions||[]}))}</p><a target="_blank" rel="noopener" href="/workbench?${esc(new URLSearchParams({tool:'code_read',args:JSON.stringify({repo:n.repo,path:n.file,from:n.line,to:n.line+25}),story}))}">Read source</a><button id="utBindField">Bind a database field</button>`:''}${isFunction(n)?`<p>Database function calls can have side effects. Read its definition before preparing SQL.</p><button id="utFunction">Inspect function definition</button><pre id="utFunctionOutput"></pre>`:''}${d?`<h3>Query selected ${n.column?'field':'table'}</h3><p class="ut-muted">${esc(n.db)} · ${esc(model.env)}. Add a tenant/entity filter before running. The initial predicate returns no rows.</p><label>Read-only SQL<textarea id="utSql" rows="5" spellcheck="false">${esc(d.sql)}</textarea></label><button id="utQuery">Run read-only query</button><pre id="utQueryOutput" role="status"></pre><a id="utQueryView" hidden target="_blank" rel="noopener">Open query results</a>`:''}<h3>Connections (${edges.length})</h3>${edges.map(e=>`<details class="ut-state-detail"><summary>${esc(e.label)} · ${esc(e.certainty)}</summary><p>${esc(e.from)} → ${esc(e.to)}</p><pre>${esc(pretty(e.evidence))}</pre>${e.assumption?`<p>${esc(e.assumption)}</p>`:''}</details>`).join('')}`;
 if($('utExpand'))$('utExpand').onclick=()=>{if(expanded.has(id))expanded.delete(id);else expanded.add(id);draw();inspect(id);};
 if($('utEditSelected'))$('utEditSelected').onclick=()=>{$('utEditor').open=true;$('utUrl').focus();};
 if($('utQuery'))$('utQuery').onclick=async()=>{const b=$('utQuery');b.disabled=true;$('utQueryView').hidden=true;$('utQueryOutput').textContent='Running read-only query…';try{const r=await tool('pg_query',{...d,sql:$('utSql').value});$('utQueryOutput').textContent=pretty(r);if(r.view){$('utQueryView').href=r.view;$('utQueryView').hidden=false;}}catch(e){$('utQueryOutput').textContent=e.message;}finally{b.disabled=false;}};
 if($('utFunction'))$('utFunction').onclick=async()=>{try{$('utFunctionOutput').textContent=pretty((await tool('pg_function',{env:model.env,name:n.db+':'+n.object})).filter(o=>n.signature===undefined||String(o.signature??o.args??'').trim().replace(/\s+/g,' ')===n.signature));}catch(e){$('utFunctionOutput').textContent=e.message;}};
 if($('utBindField'))$('utBindField').onclick=()=>bindingForm(n);
}
function bindingForm(n){
 if($('utFieldForm'))return;
 const resources=model.nodes.filter(n=>['table','function','procedure'].includes(n.kind));
 $('utBindField').insertAdjacentHTML('afterend',`<div id="utFieldForm"><h3>Bind this source state to a field</h3><p class="ut-source">${esc(n.repo)} @ ${esc(n.sha?.slice(0,12))}<br>${esc(n.file)}:${esc(n.line)}</p><label>Database alias<input id="utFieldDb" list="utDatabases"></label><datalist id="utDatabases">${[...new Set(resources.map(n=>n.db))].map(db=>`<option value="${esc(db)}">`).join('')}</datalist><label>Object kind<select id="utFieldKind"><option value="table">Table</option><option value="function">Function result</option></select></label><label>Schema and object<input id="utFieldObject" list="utObjects" placeholder="sales.orders"></label><datalist id="utObjects">${resources.map(n=>`<option value="${esc(n.object)}">`).join('')}</datalist><button id="utLoadFields">Load catalog fields</button><label>Field<select id="utFieldColumn" disabled><option value="">Load an exact catalog object first</option></select></label><label>Evidence / reason<textarea id="utFieldReason" rows="3" placeholder="SQL or mapper source establishing this binding"></textarea></label><button id="utSaveField" disabled>Save binding & rebuild</button><p id="utFieldStatus" role="status"></p></div>`);
 $('utLoadFields').onclick=async()=>{const b=$('utLoadFields');b.disabled=true;try{const kind=$('utFieldKind').value,rows=await tool(kind==='table'?'pg_table':'pg_function',{env:model.env,name:$('utFieldDb').value+':'+$('utFieldObject').value,body:false});if(rows.length!==1)throw Error('Select one exact database object.');const columns=kind==='table'?rows[0].columns:(rows[0].arg_list||[]).filter(c=>['out','table','inout'].includes(c.mode));if(!columns?.length)throw Error('No catalog fields were found for this object.');$('utFieldColumn').innerHTML=columns.map(c=>`<option value="${esc(c.name)}">${esc(c.name)} · ${esc(c.type)}</option>`).join('');$('utFieldColumn').disabled=false;$('utSaveField').disabled=false;$('utFieldStatus').textContent='Catalog fields loaded. Add the source evidence before saving.';}catch(e){$('utFieldStatus').textContent=e.message;}finally{b.disabled=false;}};
 for(const id of ['utFieldDb','utFieldObject','utFieldKind'])$(id).oninput=()=>{$('utFieldColumn').disabled=true;$('utSaveField').disabled=true;};
 $('utSaveField').onclick=()=>busy(async()=>{if(!$('utFieldReason').value.trim())throw Error('Add a source reason for the field binding.');const binding={service:n.service,repo:n.repo,sha:n.sha,file:n.file,line:n.line,db:$('utFieldDb').value,object:$('utFieldObject').value,column:$('utFieldColumn').value,reason:$('utFieldReason').value},b=JSON.parse($('utBindings').value),key=f=>JSON.stringify([f.service,f.repo,f.sha,f.file,f.line,f.db,f.object,f.column]);b.fields=(b.fields||[]).filter(f=>key(f)!==key(binding));b.fields.push(binding);$('utBindings').value=pretty(b);await build(false);});
 $('utFieldDb').focus();
}
function download(text,type,name){const url=URL.createObjectURL(new Blob([text],{type})),a=document.createElement('a');a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);}
function svg(){const l=dtUiTraceLayout.project(model,[...expanded]),byId=new Map(l.nodes.map(n=>[n.id,n])),width=Math.max(1000,...l.nodes.map(n=>n.x+n.w+30)),height=Math.max(400,...l.nodes.map(n=>n.y+n.h+30));return `<svg xmlns="http://www.w3.org/2000/svg" width="${width}" height="${height}" viewBox="0 0 ${width} ${height}"><defs><marker id="arrow" markerWidth="8" markerHeight="8" refX="7" refY="4" orient="auto"><path d="M0,0 L8,4 L0,8 Z" fill="#666"/></marker></defs><rect width="100%" height="100%" fill="#fbfbfa"/>${l.containers.map(c=>`<rect x="${c.x}" y="${c.y}" width="${c.w}" height="${c.h}" fill="#eef2fb" stroke="#ccc"/><text x="${c.x+10}" y="${c.y+22}" font-family="sans-serif">${esc(c.name)}</text>`).join('')}${l.edges.map(e=>{const a=byId.get(e.from),b=byId.get(e.to);if(!a||!b)return '';return `<g><title>${esc(e.label+' · '+e.certainty)}</title><path d="M${a.x+a.w},${a.y+a.h/2} L${b.x},${b.y+b.h/2}" fill="none" stroke="${({observed:'#16a34a',static:'#2563eb',detected:'#2563eb',declared:'#ea580c',candidate:'#ea580c',catalog:'#7c3aed'})[e.certainty]||'#666'}" ${['declared','candidate'].includes(e.certainty)?'stroke-dasharray="6 4"':''} marker-end="url(#arrow)"/></g>`;}).join('')}${l.nodes.map(n=>`<g><title>${esc(n.name)}</title><rect x="${n.x}" y="${n.y}" width="${n.w}" height="${n.h}" rx="6" fill="#fff" stroke="#8796b0"/>${n.kind==='ui'&&n.state.image?`<image x="${n.x+8}" y="${n.y+40}" width="${n.w-16}" height="${n.h-50}" href="data:${esc(n.state.image.mimeType)};base64,${esc(n.state.image.data)}"/>`:''}<text x="${n.x+12}" y="${n.y+25}" font-size="12" fill="#222" font-family="sans-serif">${esc(n.name?.slice(0,42))}</text></g>`).join('')}</svg>`;}
$('utNew').onclick=()=>{recipe=null;resultId=null;steps=[];$('utRecipe').value='';$('utId').value='';$('utName').value='';$('utUrl').value='';$('utBindings').value='{"services":[],"fields":[],"transports":[]}';renderSteps();runtimeParams();$('utEditor').open=true;$('utId').focus();};
$('utRecipe').onchange=()=>busy(async()=>{if(!$('utRecipe').value)return;edit(await tool('ui_trace_list',{id:$('utRecipe').value}));resultId=null;status('Recipe loaded. Build reads retained evidence; Replay executes its UI actions.');});
$('utAddStep').onclick=()=>{steps.push({action:'click',role:'button',name:''});renderSteps();};$('utSave').onclick=()=>busy(save);$('utBuild').onclick=()=>busy(()=>build(false));$('utReplay').onclick=()=>busy(()=>build(true));$('utUrl').onchange=runtimeParams;
$('utCancel').onclick=async()=>{if(!job)return;try{await tool('job_cancel',{job});status('Cancellation requested; browser cleanup is running.');}catch(e){status(e.message,true);}};
$('utFit').onclick=()=>canvas?.fit();$('utZoomIn').onclick=()=>canvas?.run('view.zoom.in');$('utZoomOut').onclick=()=>canvas?.run('view.zoom.out');$('utCollapse').onclick=()=>{expanded.clear();draw();if(selection)inspect(selection);};$('utSearch').oninput=outline;
$('utJson').onclick=()=>{if(model)download(pretty(model),'application/json',model.id+'-evidence.json');};$('utSvg').onclick=()=>{if(model)download(svg(),'image/svg+xml',model.id+'-diagram.svg');};$('utLink').onclick=async()=>{try{await navigator.clipboard.writeText(location.href);status('Diagram link copied. Live actions require the same authenticated task.');}catch{status('Copy this URL: '+location.href);}};
addEventListener('pagehide',()=>{resizeGuard?.disconnect();removeEventListener('resize',preserveCamera);canvas?.destroy();});
try{await list();if(resultId)await loadResult(resultId);else if(params.get('id'))edit(await tool('ui_trace_list',{id:params.get('id')}));}catch(e){status(e.message,true);}
